{
  "claims": [
    {
      "claim_text": "A shared cache stores responses for reuse by more than one user.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 0 directly defines a shared cache as storing responses for reuse by more than one user.",
      "citations": [
        {
          "index": 0,
          "quote": "A \"shared cache\" is a cache that stores responses for reuse by more than one user"
        }
      ]
    },
    {
      "claim_text": "A private cache is dedicated to a single user.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 0 states a private cache is dedicated to a single user.",
      "citations": [
        {
          "index": 0,
          "quote": "A \"private cache\", in contrast, is dedicated to a single user"
        }
      ]
    },
    {
      "claim_text": "Origin servers normally set freshness with the Expires header or the max-age directive.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 1 says the primary mechanism for determining freshness is for an origin server to provide an explicit expiration time using either the Expires header field or the max-age response directive.",
      "citations": [
        {
          "index": 1,
          "quote": "The primary mechanism for determining freshness is for an origin server to provide an explicit expiration time in the future, using either the Expires header field (Section 5.3) or the max-age response directive (Section 5.2.2.1)."
        }
      ]
    },
    {
      "claim_text": "When neither an explicit expiration time is present, a cache may assign a heuristic expiration time.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 2 states that since origin servers do not always provide explicit expiration times, a cache MAY assign a heuristic expiration time when an explicit time is not specified.",
      "citations": [
        {
          "index": 2,
          "quote": "Since origin servers do not always provide explicit expiration times, a cache MAY assign a heuristic expiration time when an explicit time is not specified"
        }
      ]
    },
    {
      "claim_text": "A cache must not use a heuristic when an explicit expiration time is present.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 3 states a cache MUST NOT use heuristics to determine freshness when an explicit expiration time is present in the stored response.",
      "citations": [
        {
          "index": 3,
          "quote": "A cache MUST NOT use heuristics to determine freshness when an explicit expiration time is present in the stored response."
        }
      ]
    },
    {
      "claim_text": "With Last-Modified, a typical heuristic is 10% of the time since that date.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 4 encourages a heuristic expiration value no more than some fraction of the interval since Last-Modified, and says a typical setting might be 10%.",
      "citations": [
        {
          "index": 4,
          "quote": "caches are encouraged to use a heuristic expiration value that is no more than some fraction of the interval since that time. A typical setting of this fraction might be 10%."
        }
      ]
    },
    {
      "claim_text": "A response last modified 30 days ago could be treated as fresh for about 3 days.",
      "verdict": "UNSUPPORTED",
      "reasoning": "The passages state a typical heuristic fraction might be 10% of the interval since Last-Modified, but they do not state or imply this specific 30-day/3-day example or that such a response 'could be treated as fresh' for that period.",
      "citations": []
    },
    {
      "claim_text": "The Age header is the cache's estimate of the number of seconds since the origin generated or validated the response.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 5 states the Age field value is the cache's estimate of the number of seconds since the origin server generated or validated the response.",
      "citations": [
        {
          "index": 5,
          "quote": "The Age field value is the cache's estimate of the number of seconds since the origin server generated or validated the response."
        }
      ]
    },
    {
      "claim_text": "A max-stale request directive without a value accepts a stale response of any age.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 7 states that if no value is assigned to max-stale, then the client will accept a stale response of any age.",
      "citations": [
        {
          "index": 7,
          "quote": "If no value is assigned to max-stale, then the client will accept a stale response of any age."
        }
      ]
    },
    {
      "claim_text": "s-maxage overrides max-age and Expires for a shared cache.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 9 states that for a shared cache, the maximum age specified by s-maxage overrides the maximum age specified by either max-age or the Expires header field.",
      "citations": [
        {
          "index": 9,
          "quote": "The s-maxage response directive indicates that, for a shared cache, the maximum age specified by this directive overrides the maximum age specified by either the max-age directive or the Expires header field."
        }
      ]
    },
    {
      "claim_text": "proxy-revalidate is the analogue of must-revalidate that does not apply to private caches.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 8 states proxy-revalidate is analogous to must-revalidate except that proxy-revalidate does not apply to private caches.",
      "citations": [
        {
          "index": 8,
          "quote": "This is analogous to must-revalidate (Section 5.2.2.2), except that proxy-revalidate does not apply to private caches."
        }
      ]
    }
  ]
}
